export function getTokyoRoadPaths(): TokyoMapPoint[][] {
  return TOKYO_ROAD_PATHS.map((path) =>
    path.split(";").map((coordinate) => {
      const [longitude, latitude] = coordinate.split(",").map(Number);
      return {
        x: (longitude / 10000) / longitudeSpan,
        y: 1 - (latitude / 10000) / latitudeSpan,
      };
    }),
  );
}
